-- The table is resolved before the column is looked at. `42P01` on both.
-- @setup
CREATE TABLE ss (id serial PRIMARY KEY, b bigserial, i int GENERATED ALWAYS AS IDENTITY, j int GENERATED BY DEFAULT AS IDENTITY, plain int, "MixCol" serial, "select" serial);
CREATE TABLE "Mixed" (id serial);
-- @test
-- @no-profile-lock: a SELECT with no FROM; no scan runs, so no index is selected on either profile
-- @expect-error: relation "nosuch" does not exist
SELECT pg_get_serial_sequence('nosuch', 'nosuch');
